 "content": "def transform(grid):
    out = [row[:] for row in grid]
    zero_cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 0]
    rr = sorted(set(r for r, c in zero_cells))
    cc = sorted(set(c for r, c in zero_cells))
    # The 2x2 zero marker erases its two columns; the rows containing it retain only color 2.
    for r in range(len(out)):
        for c in cc:
            if out[r][c] != 2:
                out[r][c] = 0
    for r in rr:
        for c in range(len(out[r])):
            if out[r][c] != 2:
                out[r][c] = 0
    return out
